splash_code:
height: Fill
flow: Down
spacing: 6

fn add_todo() {
  let text = mod.state.app.new_text
  if text != "" {
    mod.state.app.todos[mod.state.app.count] = {
      text: text
      done: false
      tag: ""
    }
    mod.state.app.count = mod.state.app.count + 1
    mod.state.app.new_text = ""
    mod.state.app.version = mod.state.app.version + 1
  }
}

View{
  width: Fill height: Fit flow: Right spacing: 8 align: VCenter
  TextInput{
    width: Fill height: Fit
    text: "" + mod.state.app.new_text
    empty_text: "New task — press Enter or click Add..."
    on_change: |text|{ mod.state.app.new_text = text }
    on_return: || add_todo()
  }
  Button{
    text: "Add"
    padding: Inset{left: 14 right: 14 top: 8 bottom: 8}
    draw_bg +: { color: #x3b82f6 radius: 7.0 }
    draw_text +: { color: #xffffff text_style: theme.font_bold {font_size: 12} }
    on_click: || add_todo()
  }
}

search_input := TextInput{
  width: Fill height: Fit
  text: "" + mod.state.app.search
  empty_text: "Search tasks..."
  on_change: |text|{
    mod.state.app.search = text
    mod.state.app.version = mod.state.app.version + 1
  }
}

View{width: Fill height: 1 show_bg: true draw_bg +: {color: #x2e3541}}

ScrollYView{
  width: Fill
  height: Fill
  flow: Down
  spacing: 6

  let query = mod.state.app.search
  let shown = 0
  let i = 0
  while i < mod.state.app.count {
    let item_index = i
    let todo = mod.state.app.todos[item_index]
    let show = true
    if query != "" {
      let parts = todo.text.split(query)
      show = parts[0] != todo.text
    }
    if show {
      shown = shown + 1
      if todo.done {
        View{
          width: Fill height: Fit flow: Right spacing: 8 align: VCenter
          padding: Inset{left: 12 right: 12 top: 9 bottom: 9}
          show_bg: true new_batch: true
          draw_bg +: { color: #x14291e radius: 8.0 }
          Button{
            text: "Done"
            padding: Inset{left: 8 right: 8 top: 4 bottom: 4}
            draw_bg +: { color: #x16a34a radius: 5.0 }
            draw_text +: { text_style: theme.font_regular {font_size: 10} color: #xffffff }
            on_click: ||{
              mod.state.app.todos[item_index].done = false
              mod.state.app.version = mod.state.app.version + 1
            }
          }
          Label{
            width: Fill text: todo.text
            draw_text +: { text_style: theme.font_regular {font_size: 12} color: #x6db885 }
          }
          Button{
            text: "Remove"
            padding: Inset{left: 8 right: 8 top: 4 bottom: 4}
            draw_bg +: { color: #x374151 radius: 5.0 }
            draw_text +: { text_style: theme.font_regular {font_size: 10} color: #x9ca3af }
            on_click: ||{
              mod.state.app.todos.remove(item_index)
              mod.state.app.count = mod.state.app.count - 1
              mod.state.app.version = mod.state.app.version + 1
            }
          }
        }
      }
      else {
        View{
          width: Fill height: Fit flow: Right spacing: 8 align: VCenter
          padding: Inset{left: 12 right: 12 top: 9 bottom: 9}
          show_bg: true new_batch: true
          draw_bg +: { color: #x1e2430 radius: 8.0 }
          Button{
            text: "Todo"
            padding: Inset{left: 8 right: 8 top: 4 bottom: 4}
            draw_bg +: { color: #x334155 radius: 5.0 }
            draw_text +: { text_style: theme.font_regular {font_size: 10} color: #x94a3b8 }
            on_click: ||{
              mod.state.app.todos[item_index].done = true
              mod.state.app.version = mod.state.app.version + 1
            }
          }
          Label{
            width: Fill text: todo.text
            draw_text +: { text_style: theme.font_regular {font_size: 12} color: #xe2e8f0 }
          }
          Button{
            text: "Remove"
            padding: Inset{left: 8 right: 8 top: 4 bottom: 4}
            draw_bg +: { color: #x374151 radius: 5.0 }
            draw_text +: { text_style: theme.font_regular {font_size: 10} color: #x9ca3af }
            on_click: ||{
              mod.state.app.todos.remove(item_index)
              mod.state.app.count = mod.state.app.count - 1
              mod.state.app.version = mod.state.app.version + 1
            }
          }
        }
      }
    }
    i = i + 1
  }

  if shown == 0 {
    if mod.state.app.count == 0 {
      View{
        width: Fill height: Fit align: Center
        padding: Inset{top: 40 bottom: 40}
        Label{
          text: "No tasks yet — add one above"
          draw_text +: { text_style: theme.font_regular {font_size: 13} color: #x64748b }
        }
      }
    }
    if mod.state.app.count > 0 {
      View{
        width: Fill height: Fit align: Center
        padding: Inset{top: 40 bottom: 40}
        Label{
          text: "No tasks match your search"
          draw_text +: { text_style: theme.font_regular {font_size: 13} color: #x64748b }
        }
      }
    }
  }
}
